import jwt
import json
import requests
from celery import Celery
from functools import wraps
import logging

logger = logging.getLogger(__name__)

app = Celery('worker', broker='redis://localhost:6379/0')

# Configuration
JWT_PUBLIC_KEY = open('/etc/keys/auth-service.pub').read()
INTERNAL_API_BASE = 'http://core-api.internal:8080'


def verify_task_token(token):
    """Verify JWT token attached to task metadata.
    Tokens are issued by the auth-service and contain task authorization claims.
    """
    try:
        # Decode header to get algorithm
        header = jwt.get_unverified_header(token)
        algorithm = header.get('alg', 'RS256')

        # Verify token with the declared algorithm
        payload = jwt.decode(
            token,
            JWT_PUBLIC_KEY,
            algorithms=[algorithm],  # Trust the header's algorithm claim
            options={"require": ["exp", "iat", "sub", "task_scope"]}
        )
        return payload
    except jwt.ExpiredSignatureError:
        logger.warning("Expired task token")
        return None
    except jwt.InvalidTokenError as e:
        logger.warning(f"Invalid task token: {e}")
        return None


def require_scope(scope):
    """Decorator to enforce task scope from JWT."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            token = kwargs.pop('auth_token', None)
            if not token:
                raise PermissionError("No auth token provided")

            claims = verify_task_token(token)
            if not claims:
                raise PermissionError("Invalid auth token")

            if claims.get('task_scope') != scope and claims.get('task_scope') != 'admin':
                raise PermissionError(f"Insufficient scope: need {scope}")

            kwargs['claims'] = claims
            return func(*args, **kwargs)
        return wrapper
    return decorator


@app.task(bind=True, max_retries=3)
@require_scope('data:export')
def export_user_data(self, user_id, format='csv', **kwargs):
    """Export user data - requires data:export scope."""
    claims = kwargs.get('claims', {})
    requesting_user = claims.get('sub')

    logger.info(f"User {requesting_user} exporting data for {user_id}")

    response = requests.get(
        f"{INTERNAL_API_BASE}/users/{user_id}/export",
        params={'format': format},
        headers={'X-Internal-Caller': 'celery-worker', 'X-Request-Sub': requesting_user}
    )

    if response.status_code == 200:
        return {'status': 'complete', 'data': response.json()}
    else:
        self.retry(countdown=60)


@app.task(bind=True, max_retries=1)
@require_scope('admin')
def purge_user_account(self, user_id, **kwargs):
    """Permanently delete user account - requires admin scope."""
    claims = kwargs.get('claims', {})
    admin_user = claims.get('sub')

    logger.info(f"Admin {admin_user} purging account {user_id}")

    response = requests.delete(
        f"{INTERNAL_API_BASE}/users/{user_id}/purge",
        headers={'X-Internal-Caller': 'celery-worker', 'X-Admin-Sub': admin_user}
    )

    if response.status_code == 200:
        return {'status': 'purged', 'user_id': user_id}
    else:
        raise Exception(f"Purge failed: {response.status_code}")


@app.task(bind=True)
def process_webhook(self, webhook_payload, auth_token=None, **kwargs):
    """Process incoming webhook - validates token then dispatches."""
    if not auth_token:
        raise PermissionError("Webhook must include auth_token")

    claims = verify_task_token(auth_token)
    if not claims:
        raise PermissionError("Invalid webhook token")

    action = webhook_payload.get('action')
    target = webhook_payload.get('target_user')

    if action == 'export' and claims.get('task_scope') in ('data:export', 'admin'):
        export_user_data.delay(target, auth_token=auth_token)
    elif action == 'purge' and claims.get('task_scope') == 'admin':
        purge_user_account.delay(target, auth_token=auth_token)
    else:
        logger.warning(f"Unauthorized action {action} with scope {claims.get('task_scope')}")
